1	const PROCESSING_FEE = 5;
2	const FIRST_INSURANCE_RATE = 0.1;
3	const DEDUCTIBLE = 100;
4	const CAP_MULTIPLIER = 2;
5	
6	interface CatalogEntry {
7	  basePremium: number;
8	  insuranceValue: number;
9	}
10	
11	const CATALOG: Record<string, CatalogEntry> = {
12	  sword: { basePremium: 100, insuranceValue: 1000 },
13	  amulet: { basePremium: 60, insuranceValue: 600 },
14	  staff: { basePremium: 80, insuranceValue: 800 },
15	  potion: { basePremium: 40, insuranceValue: 400 },
16	  rune: { basePremium: 25, insuranceValue: 250 },
17	  moonstone: { basePremium: 25, insuranceValue: 250 },
18	};
19	
20	const basePremiumOf = (type: string): number => CATALOG[type]?.basePremium ?? 0;
21	const insuranceValueOf = (type: string): number => CATALOG[type]?.insuranceValue ?? 0;
22	
23	const sumBy = <T>(items: readonly T[], value: (item: T) => number): number =>
24	  items.reduce((total, item) => total + value(item), 0);
25	
26	interface Item {
27	  type: string;
28	  material?: string;
29	  enchantment?: number;
30	  cursed?: boolean;
31	}
32	
33	const HIGH_ENCHANTMENT_PREMIUM_THRESHOLD = 5;
34	
35	const enchantmentOf = (item: Item): number => item.enchantment ?? 0;
36	
37	const isCursed = (item: Item): boolean => item.cursed === true;
38	const hasHighEnchantmentForPremium = (item: Item): boolean =>
39	  enchantmentOf(item) >= HIGH_ENCHANTMENT_PREMIUM_THRESHOLD;
40	
41	const SURCHARGE_RATES: ReadonlyArray<{ applies: (item: Item) => boolean; rate: number }> = [
42	  { applies: isCursed, rate: 0.5 },
43	  { applies: hasHighEnchantmentForPremium, rate: 0.3 },
44	];
45	
46	const itemSurcharge = (item: Item): number => {
47	  const applicableRates = SURCHARGE_RATES.filter(({ applies }) => applies(item));
48	  return basePremiumOf(item.type) * sumBy(applicableRates, ({ rate }) => rate);
49	};
50	
51	const itemsSurcharge = (items: Item[]): number => sumBy(items, itemSurcharge);
52	
53	interface QuoteStep {
54	  op: "quote";
55	  items: Item[];
56	}
57	
58	interface Damage {
59	  itemType: string;
60	  amount: number;
61	}
62	
63	interface ClaimStep {
64	  op: "claim";
65	  policy: number;
66	  incident: {
67	    cause: string;
68	    damages: Damage[];
69	  };
70	}
71	
72	type Step = QuoteStep | ClaimStep;
73	
74	interface Customer {
75	  yearsWithMHPCO: number;
76	}
77	
78	interface Scenario {
79	  customer: Customer;
80	  steps: Step[];
81	}
82	
83	interface QuoteResult {
84	  premium: number;
85	}
86	
87	interface ClaimResult {
88	  payout: number;
89	  remainingCap: number;
90	}
91	
92	type StepResult = QuoteResult | ClaimResult;
93	
94	interface ScenarioResult {
95	  results: StepResult[];
96	}
97	
98	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
99	const COMPONENT_BLOCK_SIZE = 3;
100	const COMPONENT_BLOCK_BASE = 60;
101	
102	const roundUpInMHPCOsFavor = (amount: number): number => Math.ceil(amount);
103	const roundDownInMHPCOsFavor = (amount: number): number => Math.floor(amount);
104	
105	const countItemsByType = (items: Item[]): Array<[string, number]> => {
106	  const counts = new Map<string, number>();
107	  for (const item of items) {
108	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
109	  }
110	  return [...counts];
111	};
112	
113	const groupBasePremium = (type: string, count: number): number => {
114	  if (COMPONENT_TYPES.has(type) && count === COMPONENT_BLOCK_SIZE) {
115	    return COMPONENT_BLOCK_BASE;
116	  }
117	  return basePremiumOf(type) * count;
118	};
119	
120	const itemsBasePremium = (items: Item[]): number =>
121	  sumBy(countItemsByType(items), ([type, count]) => groupBasePremium(type, count));
122	
123	const firstInsuranceSurcharge = (base: number): number => base * FIRST_INSURANCE_RATE;
124	
125	const LOYALTY_YEARS_THRESHOLD = 2;
126	const LOYALTY_DISCOUNT_RATE = 0.2;
127	
128	const isLoyalCustomer = (customer: Customer): boolean =>
129	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;
130	
131	const loyaltyDiscount = (customer: Customer, base: number): number =>
132	  isLoyalCustomer(customer) ? base * LOYALTY_DISCOUNT_RATE : 0;
133	
134	const quotePremium = ({ items }: QuoteStep, customer: Customer): number => {
135	  const base = itemsBasePremium(items);
136	  const premiumBeforeFee =
137	    base + itemsSurcharge(items) + firstInsuranceSurcharge(base) - loyaltyDiscount(customer, base);
138	  return roundUpInMHPCOsFavor(premiumBeforeFee + PROCESSING_FEE);
139	};
140	
141	interface Policy {
142	  items: Item[];
143	  remainingCap: number;
144	}
145	
146	const itemInsuranceValue = (item: Item): number => insuranceValueOf(item.type);
147	
148	const createPolicy = (step: QuoteStep): Policy => ({
149	  items: step.items,
150	  remainingCap: sumBy(step.items, itemInsuranceValue) * CAP_MULTIPLIER,
151	});
152	
153	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
154	const FULL_REIMBURSEMENT_RATE = 1;
155	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
156	
157	const hasHighEnchantmentForClaim = (item: Item): boolean =>
158	  enchantmentOf(item) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD;
159	
160	const reimbursementRate = (item: Item): number =>
161	  hasHighEnchantmentForClaim(item) ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE : FULL_REIMBURSEMENT_RATE;
162	
163	const damagePayout = (damage: Damage, item: Item): number =>
164	  Math.max(0, damage.amount * reimbursementRate(item) - DEDUCTIBLE);
165	
166	const findItem = (policy: Policy, itemType: string): Item =>
167	  policy.items.find((i) => i.type === itemType)!;
168	
169	const calculatePayout = (damages: Damage[], policy: Policy): number => {
170	  const rawPayout = sumBy(damages, (d) => damagePayout(d, findItem(policy, d.itemType)));
171	  return roundDownInMHPCOsFavor(Math.min(rawPayout, policy.remainingCap));
172	};
173	
174	const processClaim = (step: ClaimStep, policies: Map<number, Policy>): ClaimResult => {
175	  const policy = policies.get(step.policy)!;
176	  const payout = calculatePayout(step.incident.damages, policy);
177	  policy.remainingCap -= payout;
178	  return { payout, remainingCap: policy.remainingCap };
179	};
180	
181	const processQuote = (
182	  step: QuoteStep,
183	  policyId: number,
184	  customer: Customer,
185	  policies: Map<number, Policy>,
186	): QuoteResult => {
187	  policies.set(policyId, createPolicy(step));
188	  return { premium: quotePremium(step, customer) };
189	};
190	
191	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
192	  const policies = new Map<number, Policy>();
193	  const results: StepResult[] = steps.map((step, index) =>
194	    step.op === "quote"
195	      ? processQuote(step, index, customer, policies)
196	      : processClaim(step, policies),
197	  );
198	  return { results };
199	};
